    description text DEFAULT ''::text NOT NULL,
    api_key text NOT NULL,
    credential_info text DEFAULT ''::text NOT NULL,
    credential_key_version text DEFAULT 'v1'::text NOT NULL,
    credential_fingerprint text DEFAULT ''::text NOT NULL,
    margin_mode smallint DEFAULT 0 NOT NULL,
    position_mode smallint DEFAULT 0 NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
