    CONSTRAINT chk_venues_margin_mode CHECK ((margin_mode = ANY (ARRAY[0, 1, 2]))),
    CONSTRAINT chk_venues_market CHECK ((market = ANY (ARRAY[1, 2, 3]))),
    CONSTRAINT chk_venues_perp_modes CHECK (((market <> 2) OR ((margin_mode = ANY (ARRAY[1, 2])) AND (position_mode = ANY (ARRAY[1, 2]))))),
    CONSTRAINT chk_venues_position_mode CHECK ((position_mode = ANY (ARRAY[0, 1, 2]))),
    CONSTRAINT chk_venues_spot_modes CHECK (((market <> 1) OR ((margin_mode = 0) AND (position_mode = 0)))),
    CONSTRAINT chk_venues_status CHECK ((status = ANY (ARRAY[1, 2, 3, 4])))
);


